UPDATE REFDATA.APP_METRIC
   SET METRIC_NM = 'active_count', DATA_CATEGORY = 'ONCHAIN', UPDATED_AT = now()
 WHERE APP_ID = 2 AND METRIC_NM = 'active_address_count';
UPDATE REFDATA.APP_METRIC
   SET METRIC_NM = 'transfers_volume_to_exchanges_sum', DATA_CATEGORY = 'ONCHAIN', UPDATED_AT = now()
 WHERE APP_ID = 2 AND METRIC_NM = 'exchange_inflow_volume';
UPDATE REFDATA.APP_METRIC
   SET METRIC_NM = 'transfers_volume_exchanges_net_pit', DATA_CATEGORY = 'ONCHAIN', UPDATED_AT = now()
 WHERE APP_ID = 2 AND METRIC_NM = 'exchange_netflow_pit';
UPDATE REFDATA.APP_METRIC
   SET DATA_CATEGORY = 'ONCHAIN', UPDATED_AT = now()
 WHERE APP_ID = 2
   AND METRIC_NM IN (
       'sopr', 'mvrv', 'sopr_pit', 'mvrv_z_score_pit', 'hash_rate_mean',
       'exchange_net_position_change', 'exchange_net_position_change_pit'
   );
